def _parse_progress_from_job_tracker(html_bytes):
    """Pull (map_percent, reduce_percent) from running job from job tracker
    HTML as floats, or return (None, None).

    This assumes at most one running job (designed for EMR).
    """
    # snip out the Running Jobs section (ignore the header)
    start = html_bytes.rfind(b'Running Jobs')
    if start == -1:
        return None, None
    end = html_bytes.find(b'Jobs', start + len(b'Running Jobs'))
    if end == -1:
        end = None

    html_bytes = html_bytes[start:end]

    # search it for percents
    matches = _JOB_TRACKER_HTML_RE.findall(html_bytes)
    if len(matches) >= 2:
        return float(matches[0]), float(matches[1])
    else:
        return None, None

def _progress_html_from_tunnel(self):
    """Fetch progress by calling :py:func:`urlopen` on our ssh tunnel, or
    return ``None``."""
    if not self._ssh_tunnel_url:
        return None

    tunnel_config = self._ssh_tunnel_config()
    log.debug('  Fetching progress from %s at %s' % (
        tunnel_config['name'], self._ssh_tunnel_url))

    tunnel_handle = None
    try:
        tunnel_handle = urlopen(self._ssh_tunnel_url)
        return tunnel_handle.read()
    except Exception as e:
        log.debug('    failed: %s' % str(e))
        return None
    finally:
        if tunnel_handle:
            tunnel_handle.close()
